import { useMemo, useState } from 'react';
import { Table, Badge, Pagination, Stack, Text } from '@jinx-ui/react';

// Прим.: имена компонентов/пропсов Jinx UI взяты по общепринятому соглашению
// (Table.*, Badge tone, Pagination page/pageCount/onChange) — сверьте с версией пакета.

export type User = {
  id: string | number;
  name: string;
  role: string;
  active: boolean;
};

export type UsersTableProps = {
  users: User[];
  pageSize?: number;
};

export default function UsersTable({ users, pageSize = 10 }: UsersTableProps) {
  const [page, setPage] = useState(1);

  const pageCount = Math.max(1, Math.ceil(users.length / pageSize));
  const currentPage = Math.min(page, pageCount);

  const rows = useMemo(
    () => users.slice((currentPage - 1) * pageSize, currentPage * pageSize),
    [users, currentPage, pageSize],
  );

  return (
    <Stack direction="column" style={{ gap: 'var(--jx-space-md)' }}>
      <Table>
        <Table.Head>
          <Table.Row>
            <Table.HeaderCell>Имя</Table.HeaderCell>
            <Table.HeaderCell>Роль</Table.HeaderCell>
            <Table.HeaderCell>Статус</Table.HeaderCell>
          </Table.Row>
        </Table.Head>
        <Table.Body>
          {rows.length === 0 ? (
            <Table.Row>
              <Table.Cell colSpan={3}>
                <Text tone="muted">Нет пользователей</Text>
              </Table.Cell>
            </Table.Row>
          ) : (
            rows.map((user) => (
              <Table.Row key={user.id}>
                <Table.Cell>{user.name}</Table.Cell>
                <Table.Cell>{user.role}</Table.Cell>
                <Table.Cell>
                  <Badge tone={user.active ? 'success' : 'neutral'}>
                    {user.active ? 'Активен' : 'Отключён'}
                  </Badge>
                </Table.Cell>
              </Table.Row>
            ))
          )}
        </Table.Body>
      </Table>

      {pageCount > 1 && (
        <Pagination
          page={currentPage}
          pageCount={pageCount}
          onChange={setPage}
        />
      )}
    </Stack>
  );
}

